// Разбор JSON копирайтера/адаптера с ремонтом типичных обрывов (как в маскоте)
let raw = String($input.first().json.text || $input.first().json.output || '').trim();
raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
const a = raw.indexOf('{'), b = raw.lastIndexOf('}');
if (a !== -1 && b > a) raw = raw.slice(a, b + 1);
let parsed;
try { parsed = JSON.parse(raw); }
catch (e) {
  try {
    let r = raw; const q = (r.match(/"/g) || []).length; if (q % 2 !== 0) r += '"';
    if (!r.endsWith('}')) r += ']}'.slice(r.includes('[') && !r.includes(']}') ? 0 : 1);
    parsed = JSON.parse(r);
  } catch (e2) { throw new Error('Копирайтер вернул невалидный JSON: ' + raw.slice(0, 300)); }
}
const clean = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();
const points = (Array.isArray(parsed.points) ? parsed.points : []).filter(p => p && (p.headline || p.body || (p.items || []).length)).slice(0, 7)
  .map((p, i) => ({ number: clean(p.number || String(i + 1)), headline: clean(p.headline || ''), items: (Array.isArray(p.items) ? p.items : []).map(clean).filter(Boolean).slice(0, 4), body: clean(p.body || '') }));
if (points.length < 2) throw new Error('Копирайтер вернул меньше 2 смысловых слайдов');
const cover = parsed.cover || {};
const outro = parsed.outro || {};
return [{ json: {
  title: clean(parsed.title || cover.headline || 'КАРУСЕЛЬ'),
  series: clean(parsed.series || 'ЛИЧНЫЙ ОПЫТ').toUpperCase().slice(0, 24),
  badge_icon: clean(parsed.badge_icon || '🔥').slice(0, 4),
  cover: { headline: clean(cover.headline || parsed.title || ''), accent: clean(cover.accent || ''), subtext: clean(cover.subtext || ''), stat: cover.stat && cover.stat.value ? { value: clean(cover.stat.value), desc: clean(cover.stat.desc) } : null },
  points,
  outro: { headline: clean(outro.headline || 'Сохрани себе'), accent: clean(outro.accent || ''), body: clean(outro.body || ''), items: (Array.isArray(outro.items) ? outro.items : []).map(clean).filter(Boolean).slice(0, 4) },
  post_caption: clean(parsed.post_caption || '').replace(/[*_`\[\]]/g, '').slice(0, 900),
  slides_planned: points.length + 2,
} }];

