// Сборка HTML-слайдов карусели из JSON копирайтера + решений арт-директора.
// Живёт в Code-ноде воркфлоу «56 🎠 [КАРУСЕЛЬ] МОЙ МАСКОТ». Источник: moy-n8n/workflows/src/mcarousel-build-html.js
// (сборщик scripts/build-mcarousel-wf.mjs вшивает сюда шаблоны стилей из carusel_dayly_agent).
//
// Вход:  $('Парсинг и валидация сценария').first().json — контент (title, series, cover, points[], outro, post_caption)
//        $input.first().json.text — ответ арт-директора (JSON: style, cover_pose, outro_pose, stickers[], icons{})
// Выход: по одному item на слайд с binary `data` (HTML) + общие поля: runId, jobDir, renderCommand, cleanupCommand, caption
// ============================================================================

// ---------- НАСТРОЙКИ (единственное, что обычно правят) ----------
const AUTHOR = {
  name: 'КОЛЯ WEBSANSAY',
  role: 'ИИ контент-завод',
  handle: '@websansay',
  avatar: 'file:///data/studio-engine/public/assets/author/websansay.png',
};
const ASSETS = 'file:///data/studio-engine/public/assets';          // общие ассеты с маскотом (синхронизируются из S3)
const FONTS_CSS = 'file:///data/studio-engine/public/fonts/fonts.css';
const JOBS_DIR = '/data/carousel/jobs';                              // общий том n8n ↔ n8n-media-render
const RENDER_SHIM = '/opt/shims/render-html';
const MAX_SLIDES = 10;                                               // лимит альбома Telegram
const CTA_NEXT = 'Листай дальше →';
const CTA_LAST = 'Сохрани себе';
const DEFAULT_STYLE = 'style-1-grid-cards';
const POSES = ['default', 'explaining', 'pointing', 'pointing_down_caption', 'call_to_action', 'stop_warning_hand',
  'boom_brain_explosion', 'coding_laptop', 'chatbot', 'facepalm', 'surprised', 'money', 'n8n_nodes_builder',
  'shushing_secret_insight', 'mindblown_shock'];

// ---------- ВШИТЫЕ РЕСУРСЫ (генерируются сборщиком, руками не править) ----------
const ZONES_CSS = "/* =====================================================================
   ЗОНИРОВАНИЕ СЛАЙДА 1080x1350 — общее для ВСЕХ стилей.
   Слайд условно делится на 3 части (сверху вниз):

     ┌──────────────────────────┐  ← --z-pad-top (72px)
     │  HEADER   88px           │  рубрика / бейдж слева, счётчик 01/08 справа
     ├──────────────────────────┤  ← --z-gap (40px)
     │                          │
     │  MAIN     942px          │  весь контент слайда; центрируется по
     │                          │  вертикали внутри зоны (.zone-main.top —
     │                          │  прижать к верху)
     ├──────────────────────────┤  ← --z-gap (40px)
     │  FOOTER   96px           │  автор (аватар + хэндл) слева, CTA справа
     └──────────────────────────┘  ← --z-pad-bottom (72px)

   72 + 88 + 40 + 942 + 40 + 96 + 72 = 1350.
   Стили НЕ переопределяют геометрию зон — только наполнение и цвета.
   Отладка: node scripts/generate.mjs <slug> --debug → зоны обводятся красным.
   ===================================================================== */

:root {
  --z-pad-x: 90px;
  --z-pad-top: 72px;
  --z-pad-bottom: 72px;
  --z-header-h: 88px;
  --z-footer-h: 96px;
  --z-gap: 40px;
  --z-main-h: 942px;
}

* { box-sizing: border-box; margin: 0; padding: 0; -webkit-font-smoothing: antialiased; }

body.slide {
  width: 1080px; height: 1350px; overflow: hidden; position: relative;
  display: grid;
  grid-template-rows: var(--z-header-h) var(--z-main-h) var(--z-footer-h);
  grid-template-areas: "header" "main" "footer";
  row-gap: var(--z-gap);
  padding: var(--z-pad-top) var(--z-pad-x) var(--z-pad-bottom);
}

/* --- HEADER ---------------------------------------------------------- */
.zone-header {
  grid-area: header;
  display: flex; align-items: center; justify-content: space-between; gap: 24px;
  min-width: 0;
}
.zone-header .z-label {
  display: inline-flex; align-items: center; gap: 10px;
  font-size: 22px; font-weight: 700; line-height: 1;
  letter-spacing: 0.06em; text-transform: uppercase;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.zone-header .z-counter {
  font-size: 22px; font-weight: 600; line-height: 1;
  letter-spacing: 0.04em; font-variant-numeric: tabular-nums;
  opacity: 0.6; flex-shrink: 0;
}

/* --- MAIN ------------------------------------------------------------ */
.zone-main {
  grid-area: main;
  display: flex; flex-direction: column; justify-content: center;
  min-height: 0; position: relative;
}
.zone-main.top { justify-content: flex-start; }
.zone-main.center-x { align-items: center; text-align: center; }

/* --- FOOTER ---------------------------------------------------------- */
.zone-footer {
  grid-area: footer;
  display: flex; align-items: center; justify-content: space-between; gap: 24px;
  border-top: 1px solid var(--z-footer-line, rgba(128,128,128,0.25));
  padding-top: 22px;
}
.zone-footer .z-author { display: flex; align-items: center; gap: 14px; min-width: 0; }
.zone-footer .z-avatar {
  width: 52px; height: 52px; border-radius: 50%; object-fit: cover; flex-shrink: 0;
  border: 2px solid var(--z-avatar-ring, rgba(128,128,128,0.3));
}
.zone-footer .z-handle { font-size: 24px; font-weight: 700; line-height: 1; white-space: nowrap; }
.zone-footer .z-sub { font-size: 20px; font-weight: 400; line-height: 1.2; opacity: 0.65; margin-top: 6px; }
.zone-footer .z-cta { font-size: 24px; font-weight: 700; line-height: 1; white-space: nowrap; flex-shrink: 0; }

/* --- DEBUG: обводка зон ---------------------------------------------- */
body.debug-zones .zone-header,
body.debug-zones .zone-main,
body.debug-zones .zone-footer {
  outline: 3px dashed rgba(255, 40, 40, 0.9); outline-offset: -3px;
}
body.debug-zones .zone-header::after,
body.debug-zones .zone-main::after,
body.debug-zones .zone-footer::after {
  position: absolute; right: 6px; top: 6px; font: 700 14px/1 monospace;
  color: #fff; background: rgba(255,40,40,0.9); padding: 4px 8px; border-radius: 4px;
  pointer-events: none;
}
body.debug-zones .zone-header, body.debug-zones .zone-footer { position: relative; }
body.debug-zones .zone-header::after { content: 'HEADER 88'; }
body.debug-zones .zone-main::after   { content: 'MAIN 942'; }
body.debug-zones .zone-footer::after { content: 'FOOTER 96'; }
